Lemma lapi_1RB1RD_1LC0RC_0RB1LD_1LA0LD : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
