      with (l := [SCycL 4 0; SWin 4; SWinL 1]).
    vm_compute; reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_1RB1RD_1LC0RC_0RB1LD_1LA0LD
      with (l := [SCycL 4 0; SWin 1]).
    vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB1RD_1LC0RC_0RB1LD_1LA0LD
      with (l := [SCycL 4 0; SWin 4; SWinL 4]).
    vm_compute; reflexivity.
