    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB1RD_1LC0RC_0RB1LD_1LA0LD
      with (l := [SCycL 4 0; SWin 4; SWinL 2]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB1RD_1LC0RC_0RB1LD_1LA0LD
      with (l := [SCycL 4 0; SWin 4; SWinL 3]).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB1RD_1LC0RC_0RB1LD_1LA0LD
      with (l := [SCycL 4 0; SWin 4; SWinL 6; SCycR 4; SWin 1]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB1RD_1LC0RC_0RB1LD_1LA0LD
