Theorem nqhtr_1RB1RD_1LC0RC_0RB1LD_1LA0LD : NeverQuasiHaltsTr tm_1RB1RD_1LC0RC_0RB1LD_1LA0LD.
Proof.
  apply (glue_neverqhtr tm_1RB1RD_1LC0RC_0RB1LD_1LA0LD pins_1RB1RD_1LC0RC_0RB1LD_1LA0LD Cc 1).
  - exact boot_1RB1RD_1LC0RC_0RB1LD_1LA0LD.
