Definition A1_1RB1RD_1LC0RD_1RC1LB_0LB1RA : sconf := mkC StB (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [S0] [] 0 0 []).
Definition chi_1RB1RD_1LC0RD_1RC1LB_0LB1RA : list lstep := [SCycL 2 0; SWin 4; SCycR 2; SWinR 4].

Lemma run_int_1RB1RD_1LC0RD_1RC1LB_0LB1RA : srun tm false true chi_1RB1RD_1LC0RD_1RC1LB_0LB1RA A0_1RB1RD_1LC0RD_1RC1LB_0LB1RA = Some (A1_1RB1RD_1LC0RD_1RC1LB_0LB1RA, 4, 8).
Proof. vm_compute. reflexivity. Qed.

Definition B0_1RB1RD_1LC0RD_1RC1LB_0LB1RA : sconf := mkC StB (mkS [] [S1;S0] 1 0 [S1;S1;S0]) S0 (mkS [] [] 0 0 []).
Definition B1_1RB1RD_1LC0RD_1RC1LB_0LB1RA : sconf := mkC StB (mkS [] [S1;S1] 1 1 [S1;S1;S0]) S0 (mkS [] [] 0 0 []).
(** ** The INNER anchor family -- Jp at StB *)
Definition Cin_1RB1RD_1LC0RD_1RC1LB_0LB1RA (v : positive) : cconf := (StB, (Jp v ++ [], S0, [])).
Local Notation Cin := Cin_1RB1RD_1LC0RD_1RC1LB_0LB1RA.

(** [E (2^n) = A^n C]: the value this family's count starts at. *)
Lemma epow2_1RB1RD_1LC0RD_1RC1LB_0LB1RA : forall n, Jp (pow2 n) = rep [S1;S1] n ++ [S1].
Proof. induction n; simpl; [reflexivity | rewrite IHn; reflexivity]. Qed.

(** Its own INTERIOR lap -- ordinary and affine.  Iterating it to the fill is
    where a [Theta(2^j)] lives, and [inner_to_fill_lift] keeps it inside an
    existential. *)
Definition AI0_1RB1RD_1LC0RD_1RC1LB_0LB1RA : sconf := mkC StB (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition AI1_1RB1RD_1LC0RD_1RC1LB_0LB1RA : sconf := mkC StB (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [S0] [] 0 0 []).
Definition chn_1RB1RD_1LC0RD_1RC1LB_0LB1RA : list lstep := [SCycL 2 0; SWin 4; SCycR 2; SWinR 4].

Lemma run_inner_1RB1RD_1LC0RD_1RC1LB_0LB1RA : srun tm false true chn_1RB1RD_1LC0RD_1RC1LB_0LB1RA AI0_1RB1RD_1LC0RD_1RC1LB_0LB1RA = Some (AI1_1RB1RD_1LC0RD_1RC1LB_0LB1RA, 4, 8).
Proof. vm_compute. reflexivity. Qed.

(** *** boot: the outer overflow anchor -> the first inner anchor at [pow2 j] *)
Definition BB1_1RB1RD_1LC0RD_1RC1LB_0LB1RA : sconf := mkC StB (mkS [] [S1;S1] 1 0 [S1;S0;S0]) S0 (mkS [S0] [] 0 0 []).
Definition chb_1RB1RD_1LC0RD_1RC1LB_0LB1RA : list lstep := [SCycL 2 0; SWin 4; SCycR 2; SWinR 4].

Lemma run_boot_1RB1RD_1LC0RD_1RC1LB_0LB1RA : srun tm true true chb_1RB1RD_1LC0RD_1RC1LB_0LB1RA B0_1RB1RD_1LC0RD_1RC1LB_0LB1RA = Some (BB1_1RB1RD_1LC0RD_1RC1LB_0LB1RA, 4, 8).
Proof. vm_compute. reflexivity. Qed.

(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_1RB1RD_1LC0RD_1RC1LB_0LB1RA : sconf := mkC StB (mkS [] [S1;S0] 1 0 [S1]) S0 (mkS [] [] 0 0 []).
Definition che_1RB1RD_1LC0RD_1RC1LB_0LB1RA : list lstep := [SCycL 2 0; SWin 1; SWinL 7; SCycR 2; SWinR 2; SFoldL 1].

Lemma run_exit_1RB1RD_1LC0RD_1RC1LB_0LB1RA : srun tm true true che_1RB1RD_1LC0RD_1RC1LB_0LB1RA BE0_1RB1RD_1LC0RD_1RC1LB_0LB1RA = Some (B1_1RB1RD_1LC0RD_1RC1LB_0LB1RA, 4, 10).
Proof. vm_compute. reflexivity. Qed.

(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB1RD_1LC0RD_1RC1LB_0LB1RA : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Jp q0 ++ [S1;S0]) [] j A0_1RB1RD_1LC0RD_1RC1LB_0LB1RA.
Proof.
  intros p j q0 E. destruct (JpCounter.cview_some_J p j q0 E) as (H1 & _).
  unfold Cc_1RB1RD_1LC0RD_1RC1LB_0LB1RA, cden, A0_1RB1RD_1LC0RD_1RC1LB_0LB1RA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S0] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

(** The lap ends on [S0] where the anchor has [] -- one trailing blank,
    which [lift] cannot see. *)
Lemma gei_1RB1RD_1LC0RD_1RC1LB_0LB1RA : forall p j q0, cview p = (j, Some q0) ->
  lift (cden (Jp q0 ++ [S1;S0]) [] j A1_1RB1RD_1LC0RD_1RC1LB_0LB1RA) = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct (JpCounter.cview_some_J p j q0 E) as (_ & H2).
  unfold Cc_1RB1RD_1LC0RD_1RC1LB_0LB1RA, cden, A1_1RB1RD_1LC0RD_1RC1LB_0LB1RA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  change ([S0]) with (([]) ++ [S0]).
  rewrite !lift_app_blank.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_1RB1RD_1LC0RD_1RC1LB_0LB1RA : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E.
  exists (4 * j + 8), (cden (Jp q0 ++ [S1;S0]) [] j A1_1RB1RD_1LC0RD_1RC1LB_0LB1RA).
  split; [lia|]. split; [| exact (gei_1RB1RD_1LC0RD_1RC1LB_0LB1RA p j q0 E)].
  rewrite (gsi_1RB1RD_1LC0RD_1RC1LB_0LB1RA p j q0 E).
  exact (srun_sound tm false true chi_1RB1RD_1LC0RD_1RC1LB_0LB1RA A0_1RB1RD_1LC0RD_1RC1LB_0LB1RA A1_1RB1RD_1LC0RD_1RC1LB_0LB1RA 4 8
           run_int_1RB1RD_1LC0RD_1RC1LB_0LB1RA (Jp q0 ++ [S1;S0]) [] j
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

Lemma gso_1RB1RD_1LC0RD_1RC1LB_0LB1RA : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB1RD_1LC0RD_1RC1LB_0LB1RA.
Proof.
  intros p j E. destruct (JpCounter.cview_none_J p j E) as (H1 & _).
  unfold Cc_1RB1RD_1LC0RD_1RC1LB_0LB1RA, cden, B0_1RB1RD_1LC0RD_1RC1LB_0LB1RA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_1RB1RD_1LC0RD_1RC1LB_0LB1RA : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB1RD_1LC0RD_1RC1LB_0LB1RA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1RD_1LC0RD_1RC1LB_0LB1RA) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (JpCounter.cview_none_J p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB1RD_1LC0RD_1RC1LB_0LB1RA
             = (StB, (rep [S1;S1] (S j) ++ [S1;S1;S0], S0, []))).
  { unfold cden, B1_1RB1RD_1LC0RD_1RC1LB_0LB1RA, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StB, (rep [S1;S1] (S j) ++ [S1;S1;S0], S0, []))).
  { unfold Cc_1RB1RD_1LC0RD_1RC1LB_0LB1RA. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. reflexivity.
Qed.

Lemma gsn_1RB1RD_1LC0RD_1RC1LB_0LB1RA : forall v i q0, cview v = (i, Some q0) ->
  Cin v = cden (Jp q0 ++ []) [] i AI0_1RB1RD_1LC0RD_1RC1LB_0LB1RA.
