(** ** The lap *)

Lemma lap_1RB1RD_1LC1RA_0LA1LA_0RB0LD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
