  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB1RD_1LC1RA_0LA1LA_0RB0LD p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1RD_1LC1RA_0LA1LA_0RB0LD B0_1RB1RD_1LC1RA_0LA1LA_0RB0LD B1_1RB1RD_1LC1RA_0LA1LA_0RB0LD 4 16 p j' [] []).
    + exact run_ovf_1RB1RD_1LC1RA_0LA1LA_0RB0LD.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1RD_1LC1RA_0LA1LA_0RB0LD p j' E).
    + exact (geo_1RB1RD_1LC1RA_0LA1LA_0RB0LD p j' E).
    + lia.
Qed.

