Lemma geo_1RB1RD_1LC1RA_0RA1LC_1RB0LC : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1RD_1LC1RA_0RA1LC_1RB0LC) = lift (Cc (Pos.succ p)).
