Definition pins_1RB1RD_1LC1RB_0RA1LD_1RA0LC : list Instr := [].
Definition tmw_1RB1RD_1LC1RB_0RA1LD_1RA0LC : TM := tm_wrap_trs tmm_1RB1RD_1LC1RB_0RA1LD_1RA0LC pins_1RB1RD_1LC1RB_0RA1LD_1RA0LC.
