Lemma geo_1RB1RD_1LC1RB_0RA1LD_1RA0LC : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1RD_1LC1RB_0RA1LD_1RA0LC) = lift (Cc (Pos.succ p)).
