Lemma lapil_1RB1RD_1LC1RB_0RA1LD_1RA0LC : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. exact lapi_1RB1RD_1LC1RB_0RA1LD_1RA0LC. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_1RB1RD_1LC1RB_0RA1LD_1RA0LC : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_1RB1RD_1LC1RB_0RA1LD_1RA0LC p (pow2 j)).
  - exists (4 * j + 6), (cden [] [] j BB1_1RB1RD_1LC1RB_0RA1LD_1RA0LC).
    split; [lia|]. split; [| exact (gbo_1RB1RD_1LC1RB_0RA1LD_1RA0LC j)].
    rewrite (gso_1RB1RD_1LC1RB_0RA1LD_1RA0LC p j E).
    exact (srun_sound tm true true chb_1RB1RD_1LC1RB_0RA1LD_1RA0LC B0_1RB1RD_1LC1RB_0RA1LD_1RA0LC BB1_1RB1RD_1LC1RB_0RA1LD_1RA0LC 4 6
             run_boot_1RB1RD_1LC1RB_0RA1LD_1RA0LC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (8 * j + 17), (cden [] [] j B1_1RB1RD_1LC1RB_0RA1LD_1RA0LC).
    split; [| exact (geo_1RB1RD_1LC1RB_0RA1LD_1RA0LC p j E)].
