  - destruct (lapi_1RB____0LC0RA_0LD0LD_1RA1LC p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB____0LC0RA_0LD0LD_1RA1LC B0_1RB____0LC0RA_0LD0LD_1RA1LC B1_1RB____0LC0RA_0LD0LD_1RA1LC 4 8 p j' [] []).
    + exact run_ovf_1RB____0LC0RA_0LD0LD_1RA1LC.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB____0LC0RA_0LD0LD_1RA1LC p j' E).
    + exact (geo_1RB____0LC0RA_0LD0LD_1RA1LC p j' E).
    + lia.
Qed.

