(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB____0LC1RA_1RB0LD_1LC0RA : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Jp q0 ++ [S0]) [] j A0_1RB____0LC1RA_1RB0LD_1LC0RA.
Proof.
  intros p j q0 E. destruct (JpCounter.cview_some_J p j q0 E) as (H1 & _).
  unfold Cc_1RB____0LC1RA_1RB0LD_1LC0RA, cden, A0_1RB____0LC1RA_1RB0LD_1LC0RA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S0] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gei_1RB____0LC1RA_1RB0LD_1LC0RA : forall p j q0, cview p = (j, Some q0) ->
  cden (Jp q0 ++ [S0]) [] j A1_1RB____0LC1RA_1RB0LD_1LC0RA = Cc (Pos.succ p).
Proof.
