    intros p1 j1 E1.
    exact (firex_1RB____0LC1RB_1LA1LD_1LC0RB [SRotL 1; SWin 1; SCycL 2 0; SWinL 2] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB____0LC1RB_1LA1LD_1LC0RB
