  exists (4 * j + 8), (cden (Dp q0 ++ [S0]) [] j A1_1RB____0LC1RD_1LA1LC_0LA0RD).
  split; [lia|]. split; [| exact (gei_1RB____0LC1RD_1LA1LC_0LA0RD p j q0 E)].
  rewrite (gsi_1RB____0LC1RD_1LA1LC_0LA0RD p j q0 E).
  exact (srun_sound tm false true chi_1RB____0LC1RD_1LA1LC_0LA0RD A0_1RB____0LC1RD_1LA1LC_0LA0RD A1_1RB____0LC1RD_1LA1LC_0LA0RD 4 8
           run_int_1RB____0LC1RD_1LA1LC_0LA0RD (Dp q0 ++ [S0]) [] j
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

Lemma gso_1RB____0LC1RD_1LA1LC_0LA0RD : forall p j, cview p = (S j, None) ->
