Lemma geo_1RB____0LC1RD_1LA1LC_0LA0RD : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB____0LC1RD_1LA1LC_0LA0RD) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (DpCounter.cview_none_D p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB____0LC1RD_1LA1LC_0LA0RD
             = (StA, (rep [S0;S0] (S j) ++ [S1;S1], S0, ([]) ++ [S0]))).
