(** ** The lap *)

Lemma lap_1RB____1LC1RB_0RA1LD_0LC0LC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
