    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB____1LC1RB_0RA1LD_0LC0LC B0_1RB____1LC1RB_0RA1LD_0LC0LC B1_1RB____1LC1RB_0RA1LD_0LC0LC 4 9 p j' [] []).
    + exact run_ovf_1RB____1LC1RB_0RA1LD_0LC0LC.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB____1LC1RB_0RA1LD_0LC0LC p j' E).
    + exact (geo_1RB____1LC1RB_0RA1LD_0LC0LC p j' E).
    + lia.
