    by exact lapi_1RB____1LC1RB_1RA1LD_0RB0LC.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)).
    intros p1 j1 E1. destruct j1 as [|j1'].
    + rewrite (cview_none_shape p1 0 E1).
      exact firez_A0_1RB____1LC1RB_1RA1LD_0RB0LC.
    + exact (fireo_1RB____1LC1RB_1RA1LD_0RB0LC [SRotL 1; SWin 1; SCycL 2 0; SWin 8; SCycR 2; SWin 2] (StA, S0) ltac:(vm_compute; reflexivity)
                   p1 j1' E1).
