    intros p1 j1 E1. destruct j1 as [|j1'].
    + rewrite (cview_none_shape p1 0 E1).
      exact firez_B1_1RB____1LC1RB_1RA1LD_0RB0LC.
    + exact (fireo_1RB____1LC1RB_1RA1LD_0RB0LC [SRotL 1; SWin 1] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1' E1).
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)).
    intros p1 j1 E1. destruct j1 as [|j1'].
    + rewrite (cview_none_shape p1 0 E1).
      exact firez_C0_1RB____1LC1RB_1RA1LD_0RB0LC.
    + exact (fireo_1RB____1LC1RB_1RA1LD_0RB0LC [SRotL 1; SWin 1; SCycL 2 0; SWin 8; SCycR 2; SWin 1] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1' E1).
  - (* C1 *)
