    intros p1 j1 E1. destruct j1 as [|j1'].
    + rewrite (cview_none_shape p1 0 E1).
      exact firez_C1_1RB____1LC1RB_1RA1LD_0RB0LC.
    + exact (fireo_1RB____1LC1RB_1RA1LD_0RB0LC [SRotL 1; SWin 1; SCycL 2 0; SWin 5] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1' E1).
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)).
    intros p1 j1 E1. destruct j1 as [|j1'].
    + rewrite (cview_none_shape p1 0 E1).
      exact firez_D0_1RB____1LC1RB_1RA1LD_0RB0LC.
    + exact (fireo_1RB____1LC1RB_1RA1LD_0RB0LC [] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1' E1).
  - (* D1 *)
